    /// The rows that changed among those the host held, each run folded as
    /// the reader left it. A row new at either edge, or held through a
    /// reload, is read when it is drawn.
    public var rows: [Row]
    /// How each agent the held rows open stands, from the fleet, and what
    /// each group of them comes to: a row that opens an agent draws its
    /// state from here, since the fleet moving changes no row.
    public var agents: ChatAgents?
    public var ask: AskMoved?
    public var frame: ChatFrame?
    public var keys: KeysMoved?
    public var overview: Overview?
    /// The review page open on the chat, whole, when it moved: the rows an
    /// anchor's indices count are those of the page handed over last.
    public var review: ReviewPage?
    public var settings: SettingsView?

    public init(chat: UInt64, rows: [Row], agents: ChatAgents?, ask: AskMoved?, frame: ChatFrame?, keys: KeysMoved?, overview: Overview?, review: ReviewPage?, settings: SettingsView?) {
        self.chat = chat
        self.rows = rows
        self.agents = agents
        self.ask = ask
        self.frame = frame
        self.keys = keys
        self.overview = overview
        self.review = review
        self.settings = settings
    }

    private enum CodingKeys: String, CodingKey {
        case chat
        case rows
        case agents
        case ask
        case frame
        case keys
        case overview
        case review
        case settings
    }
}

/// Everything around a chat's rows that a screen draws at once.
public struct ChatFrame: Codable, Hashable, Sendable {
    public var agent: AgentKey
    public var name: String
    public var kind: Kind
    public var phase: PhaseView
    public var composer: ComposerView
    /// The model, effort in force, and a permission or mode other than the
    /// normal one, as the composer says them.
    public var controls: ControlsSummary
    public var connection: Connection
    /// The rows are current with the agent's host.
    public var caughtUp: Bool
    /// Older rows exist below the held window.
    public var hasOlder: Bool
    /// Rows arrived above the window while the reader is in history: the
    /// new-activity affordance shows from this.
    public var arrivalsHeld: Bool
    public var queue: [QueuedRow]
    /// This client's prompts on their way: at the feed's end or in the
    /// queue, sending or perhaps never arrived.
    public var underway: [SentPrompt]
    /// This client's prompts the agent refused, until the person takes
    /// their words back into the composer.
    public var refused: [RefusedPrompt]
    /// The input answering the head ask, which a card that was not
