                keyedBy: AllowAlwaysKeys.self, forKey: .allowAlways)
            self = .allowAlways(
                subjects: try _fields.decode([String].self, forKey: .subjects),
                directories: try _fields.decode([String].self, forKey: .directories),
                mode: try _fields.decode(String.self, forKey: .mode),
                modeName: try _fields.decode(String.self, forKey: .modeName),
                scope: try _fields.decode(Scope.self, forKey: .scope))
        case .allowSimilar:
            let _fields = try _container.nestedContainer(
                keyedBy: AllowSimilarKeys.self, forKey: .allowSimilar)
            self = .allowSimilar(
                prefix: try _fields.decode([String].self, forKey: .prefix))
        case .allowNetwork:
            let _fields = try _container.nestedContainer(
                keyedBy: AllowNetworkKeys.self, forKey: .allowNetwork)
            self = .allowNetwork(
                hosts: try _fields.decode([String].self, forKey: .hosts))
        case .approvePlan:
            let _fields = try _container.nestedContainer(
                keyedBy: ApprovePlanKeys.self, forKey: .approvePlan)
            self = .approvePlan(
                mode: try _fields.decode(String.self, forKey: .mode),
                modeName: try _fields.decode(String.self, forKey: .modeName))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .allowOnce:
            var _container = encoder.singleValueContainer()
            try _container.encode("AllowOnce")
        case .allowForSession:
            var _container = encoder.singleValueContainer()
            try _container.encode("AllowForSession")
        case .denyAndStop:
            var _container = encoder.singleValueContainer()
            try _container.encode("DenyAndStop")
        case .sendBack:
            var _container = encoder.singleValueContainer()
            try _container.encode("SendBack")
        case .submit:
            var _container = encoder.singleValueContainer()
            try _container.encode("Submit")
        case .decline:
            var _container = encoder.singleValueContainer()
            try _container.encode("Decline")
        case .openLink:
            var _container = encoder.singleValueContainer()
            try _container.encode("OpenLink")
        case .grantForTurn:
            var _container = encoder.singleValueContainer()
            try _container.encode("GrantForTurn")
        case .grantForSession:
            var _container = encoder.singleValueContainer()
            try _container.encode("GrantForSession")
        case .allowAlways(let subjects, let directories, let mode, let modeName, let scope):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: AllowAlwaysKeys.self, forKey: .allowAlways)
            try _fields.encode(subjects, forKey: .subjects)
            try _fields.encode(directories, forKey: .directories)
            try _fields.encode(mode, forKey: .mode)
            try _fields.encode(modeName, forKey: .modeName)
            try _fields.encode(scope, forKey: .scope)
        case .allowSimilar(let prefix):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: AllowSimilarKeys.self, forKey: .allowSimilar)
            try _fields.encode(prefix, forKey: .prefix)
        case .allowNetwork(let hosts):
