        self.handle = handle
        self.kind = kind
        self.attention = attention
        self.cwd = cwd
        self.phaseSinceMs = phaseSinceMs
        self.host = host
        self.hostReach = hostReach
        self.children = children
        self.familyAttention = familyAttention
        self.members = members
        self.descendants = descendants
        self.backgroundJobs = backgroundJobs
        self.closeHeld = closeHeld
        self.filing = filing
        self.topLevel = topLevel
        self.native = native
        self.branch = branch
        self.exitCause = exitCause
        self.repository = repository
    }

    private enum CodingKeys: String, CodingKey {
        case agent
        case name
        case handle
        case kind
        case attention
        case cwd
        case phaseSinceMs = "phase_since_ms"
        case host
