        case children
        case familyAttention = "family_attention"
        case members
        case descendants
        case backgroundJobs = "background_jobs"
        case closeHeld = "close_held"
        case filing
        case topLevel = "top_level"
        case native
        case branch
        case exitCause = "exit_cause"
        case repository
    }
