/// An input as the client that sent it observes it.
public enum InputState: Codable, Hashable, Sendable {
    /// In flight, or accepted and waiting for its reflection. The optimistic
    /// row exists.
    case sent
    /// Accepted into the agent's queue; listed by every snapshot until it is
    /// submitted or withdrawn.
    case queued
    /// Accepted and, for a prompt, reflected by an item.
    case settled
    case rejected(Refusal)
    /// The connection dropped before a reply. Resolved only at CaughtUp from
    /// the snapshot's queue and the items; one found in neither stays here
    /// and the person decides. Nothing is resent on its own: it may have
    /// reached the agent, and agents do not drop a person's input sent twice.
    case uncertain

    private enum Tag: String, CodingKey {
        case rejected = "Rejected"
    }

    public init(from decoder: any Decoder) throws {
        if let _single = try? decoder.singleValueContainer(),
           let _name = try? _single.decode(String.self)
        {
            switch _name {
            case "Sent": self = .sent
            case "Queued": self = .queued
            case "Settled": self = .settled
            case "Uncertain": self = .uncertain
            default:
                throw DecodingError.dataCorruptedError(
                    in: _single, debugDescription: "no InputState is named \(_name)")
            }
            return
        }
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a InputState names exactly one variant"))
        }
        switch _tag {
        case .rejected:
            self = .rejected(try _container.decode(Refusal.self, forKey: .rejected))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .sent:
            var _container = encoder.singleValueContainer()
            try _container.encode("Sent")
        case .queued:
            var _container = encoder.singleValueContainer()
            try _container.encode("Queued")
        case .settled:
            var _container = encoder.singleValueContainer()
            try _container.encode("Settled")
        case .rejected(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .rejected)
        case .uncertain:
            var _container = encoder.singleValueContainer()
            try _container.encode("Uncertain")
        }
    }
}

