/// Pairing with a machine: the PIN its person reads out, or the link its
/// QR code carries.
public enum PairRequest: Codable, Hashable, Sendable {
    case pin(pin: String, addrs: [String], hostId: [UInt8]?)
    case link(String)

    private enum Tag: String, CodingKey {
        case pin = "Pin"
        case link = "Link"
    }

    private enum PinKeys: String, CodingKey {
        case pin
        case addrs
        case hostId = "host_id"
    }

    public init(from decoder: any Decoder) throws {
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a PairRequest names exactly one variant"))
        }
        switch _tag {
        case .pin:
            let _fields = try _container.nestedContainer(
                keyedBy: PinKeys.self, forKey: .pin)
            self = .pin(
                pin: try _fields.decode(String.self, forKey: .pin),
                addrs: try _fields.decode([String].self, forKey: .addrs),
                hostId: try _fields.decodeIfPresent([UInt8].self, forKey: .hostId))
        case .link:
            self = .link(try _container.decode(String.self, forKey: .link))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .pin(let pin, let addrs, let hostId):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: PinKeys.self, forKey: .pin)
            try _fields.encode(pin, forKey: .pin)
            try _fields.encode(addrs, forKey: .addrs)
            try _fields.encodeIfPresent(hostId, forKey: .hostId)
        case .link(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .link)
        }
