/// A row's place in its run.
public struct Run: Codable, Hashable, Sendable {
    /// The run's oldest held step, where an opened run draws its header.
    /// It moves as the window's low edge does, so it names no run: hold
    /// an open run by a member (see [`run_is_open`]).
    public var first: String
    /// Its newest step, where a folded run draws its one line.
    public var last: String
    public var steps: UInt32
    /// Nothing but steps follows it yet: the agent is still at it.
    public var live: Bool
    /// It starts at the oldest held rows and older history exists, so it may
    /// continue below: its counts are a floor.
    public var openBelow: Bool
    /// While the run is under way this step shows: it is the newest, or it
    /// is still running. False once the run is over.
    public var liveShown: Bool
    /// This step failed and nothing later in its turn redid it, and the
    /// turn has ended: it stays in view when the run folds.
    public var unresolvedFailure: Bool
    /// The reader opened it: a folding view's open set holds one of its
    /// steps. Always false for a view that does not fold.
    public var open: Bool
    /// What the run's steps did, on its newest step's row only.
    public var counts: RunCounts?
    /// On the oldest step a live run shows, what the steps it does not
    /// show did, for the line above it; absent elsewhere, and when it shows
    /// every step.
    public var hidden: RunCounts?
    /// For one of the run's two newest steps, how many steps follow it
    /// (none for the newest); absent for the rest.
    public var recent: UInt32?

    public init(first: String, last: String, steps: UInt32, live: Bool, openBelow: Bool, liveShown: Bool, unresolvedFailure: Bool, open: Bool, counts: RunCounts?, hidden: RunCounts?, recent: UInt32?) {
        self.first = first
        self.last = last
        self.steps = steps
        self.live = live
        self.openBelow = openBelow
        self.liveShown = liveShown
        self.unresolvedFailure = unresolvedFailure
        self.open = open
        self.counts = counts
        self.hidden = hidden
        self.recent = recent
    }

    private enum CodingKeys: String, CodingKey {
        case first
        case last
        case steps
        case live
        case openBelow = "open_below"
        case liveShown = "live_shown"
        case unresolvedFailure = "unresolved_failure"
        case open
        case counts
        case hidden
        case recent
    }
}

/// What a run's steps did.
public struct RunCounts: Codable, Hashable, Sendable {
    public var commands: UInt32
    /// Files changed, each counted once however often it changed.
    public var edits: UInt32
    /// Files read, each counted once however often it was read.
    public var reads: UInt32
    /// Searches of files or the web.
    public var searches: UInt32
    /// Folders listed.
    public var lists: UInt32
    /// Pages fetched.
    public var fetches: UInt32
    /// Subagents run, started or stopped.
    public var subagents: UInt32
    /// Tool-server calls, images and the rest.
    public var other: UInt32

    public init(commands: UInt32, edits: UInt32, reads: UInt32, searches: UInt32, lists: UInt32, fetches: UInt32, subagents: UInt32, other: UInt32) {
        self.commands = commands
        self.edits = edits
        self.reads = reads
        self.searches = searches
        self.lists = lists
        self.fetches = fetches
        self.subagents = subagents
        self.other = other
    }

    private enum CodingKeys: String, CodingKey {
        case commands
        case edits
        case reads
        case searches
        case lists
        case fetches
        case subagents
        case other
    }
}

public enum Scope: Codable, Hashable, Sendable {
    case session
    /// This project, for this person.
    case project
    /// This project, shared with everyone who works on it.
    case projectShared
    /// Every project.
    case user
    case other(String)

    private enum Tag: String, CodingKey {
        case other = "Other"
    }

    public init(from decoder: any Decoder) throws {
        if let _single = try? decoder.singleValueContainer(),
           let _name = try? _single.decode(String.self)
        {
            switch _name {
            case "Session": self = .session
            case "Project": self = .project
            case "ProjectShared": self = .projectShared
            case "User": self = .user
            default:
                throw DecodingError.dataCorruptedError(
                    in: _single, debugDescription: "no Scope is named \(_name)")
            }
            return
        }
        let _container = try decoder.container(keyedBy: Tag.self)
        guard _container.allKeys.count == 1, let _tag = _container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription: "a Scope names exactly one variant"))
        }
        switch _tag {
        case .other:
            self = .other(try _container.decode(String.self, forKey: .other))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .session:
            var _container = encoder.singleValueContainer()
            try _container.encode("Session")
        case .project:
            var _container = encoder.singleValueContainer()
            try _container.encode("Project")
        case .projectShared:
            var _container = encoder.singleValueContainer()
            try _container.encode("ProjectShared")
        case .user:
            var _container = encoder.singleValueContainer()
            try _container.encode("User")
        case .other(let _value):
            var _container = encoder.container(keyedBy: Tag.self)
            try _container.encode(_value, forKey: .other)
        }
    }
}

/// What a row says under its name, by the agent's state. What the agent is
/// working on is a fact for agents finding each other, not for this line.
public enum SecondLine: Codable, Hashable, Sendable {
    /// What it wants of the person: what it asks, or what stops it. The
    /// same words a push says.
    case said(Said)
    /// Working: the step it is running, as the chat's activity line has it.
    case step(ActivityLine)
    /// Idle: the first line of what it last said.
    case lastSaid(String)
    case exited(ExitCause)
    /// The agent's host no longer trusts this machine: it will not come
    /// back on its own, only by pairing again. The agent is only as it last
    /// said.
    case hostRevoked
    /// Starting, or nothing known yet.
    case blank

    private enum Tag: String, CodingKey {
        case said = "Said"
        case step = "Step"
        case lastSaid = "LastSaid"
